local MillSailFrameMaker = {}
local PRODUCTS = {
    iron_millsailframe = { name = "Železni okvir za jedra mlina", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni okvir za jedra mlina za mlinarje." },
    bronze_millsailframe = { name = "Bronast okvir za jedra mlina", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast okvir za jedra mlina za mlinarje." },
    silver_millsailframe = { name = "Srebrn okvir za jedra mlina", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn okvir za jedra mlina za mlinarje." },
    gilded_millsailframe = { name = "Pozlačen okvir za jedra mlina", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen okvir za jedra mlina za mlinarje." },
    jewel_set_millsailframe = { name = "Draguljast okvir za jedra mlina", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast okvir za jedra mlina za mlinarje." },
    royal_sovereign_millsailframe = { name = "Kraljevski suveren okvir za jedra mlina", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren okvir za jedra mlina z biseri za krono." },
}
local BUILDINGS = {
    millsailframe_workshop = { name = "Millsailframe delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millsailframe_house = { name = "Millsailframe hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millsailframe_atelier = { name = "Mojstrski millsailframe atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millsailframe_palace = { name = "Suverena millsailframe palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillSailFrameMaker.ironStock=14; MillSailFrameMaker.bronzeStock=12; MillSailFrameMaker.woodStock=16; MillSailFrameMaker.leatherStock=8; MillSailFrameMaker.silverStock=8; MillSailFrameMaker.goldStock=6; MillSailFrameMaker.jewelStock=4; MillSailFrameMaker.pearlStock=4
MillSailFrameMaker.productStock = {}; MillSailFrameMaker.buildings = {}; MillSailFrameMaker.maker = nil; MillSailFrameMaker.activeMaking = {}; MillSailFrameMaker.totalProducts = 0; MillSailFrameMaker.dayTimer = 0
function MillSailFrameMaker.init() MillSailFrameMaker.ironStock=14; MillSailFrameMaker.bronzeStock=12; MillSailFrameMaker.woodStock=16; MillSailFrameMaker.leatherStock=8; MillSailFrameMaker.silverStock=8; MillSailFrameMaker.goldStock=6; MillSailFrameMaker.jewelStock=4; MillSailFrameMaker.pearlStock=4; MillSailFrameMaker.productStock={}; MillSailFrameMaker.buildings={}; MillSailFrameMaker.maker=nil; MillSailFrameMaker.activeMaking={}; MillSailFrameMaker.totalProducts=0; MillSailFrameMaker.dayTimer=0; print("[MillSailFrameMaker] Royal Mill Sail Frame Maker System initialized (6 products, 4 buildings)") end
function MillSailFrameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailFrameMaker.maker={name=n or ("Jedrnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jedrnik najet: %s (spretnost: %d)",MillSailFrameMaker.maker.name,s),"success") end; return true end
function MillSailFrameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailFrameMaker.build(id) local ok,e=MillSailFrameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailFrameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailFrameMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailFrameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailFrameMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailFrameMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailFrameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailFrameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailFrameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailFrameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailFrameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailFrameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailFrameMaker.buildings==0 then return false,"Potrebna jedrna delavnica" end; if not MillSailFrameMaker.maker then return false,"Potreben jedrnik" end; return true end
function MillSailFrameMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailFrameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailFrameMaker.ironStock=MillSailFrameMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailFrameMaker.bronzeStock=MillSailFrameMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailFrameMaker.woodStock=MillSailFrameMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailFrameMaker.leatherStock=MillSailFrameMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailFrameMaker.silverStock=MillSailFrameMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailFrameMaker.goldStock=MillSailFrameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailFrameMaker.jewelStock=MillSailFrameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailFrameMaker.pearlStock=MillSailFrameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailFrameMaker.maker then t=math.max(1,t-math.floor(MillSailFrameMaker.maker.skill/13)) end; table.insert(MillSailFrameMaker.activeMaking,{id="millsailframe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailFrameMaker.completeMaking(m) local q=1.0+(MillSailFrameMaker.getQualityBonus()/100); if MillSailFrameMaker.maker then q=q+(MillSailFrameMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailFrameMaker.productStock[m.productType]=(MillSailFrameMaker.productStock[m.productType] or 0)+m.quantity; MillSailFrameMaker.totalProducts=MillSailFrameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailFrameMaker.maker then MillSailFrameMaker.maker.itemsMade=MillSailFrameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailFrameMaker.maker.skill=math.min(100,MillSailFrameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okvir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailframe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailFrameMaker.update(dt) if not _G.state then return end; MillSailFrameMaker.dayTimer=MillSailFrameMaker.dayTimer+dt; if MillSailFrameMaker.dayTimer>=30 then MillSailFrameMaker.dayTimer=0; for i=#MillSailFrameMaker.activeMaking,1,-1 do local m=MillSailFrameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailFrameMaker.completeMaking(m); table.remove(MillSailFrameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailFrameMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillSailFrameMaker.getStats() return {ironStock=MillSailFrameMaker.ironStock,bronzeStock=MillSailFrameMaker.bronzeStock,woodStock=MillSailFrameMaker.woodStock,leatherStock=MillSailFrameMaker.leatherStock,silverStock=MillSailFrameMaker.silverStock,goldStock=MillSailFrameMaker.goldStock,jewelStock=MillSailFrameMaker.jewelStock,pearlStock=MillSailFrameMaker.pearlStock,productStock=MillSailFrameMaker.productStock,numBuildings=#MillSailFrameMaker.buildings,hasMaker=MillSailFrameMaker.maker~=nil,makerName=MillSailFrameMaker.maker and MillSailFrameMaker.maker.name or "—",makerSkill=MillSailFrameMaker.maker and MillSailFrameMaker.maker.skill or 0,activeMaking=#MillSailFrameMaker.activeMaking,totalProducts=MillSailFrameMaker.totalProducts} end
return MillSailFrameMaker
